from torch.utils.cpp_extension import load_inline

square_matrix_multiply_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdio> // For printf

// Define constants
#define TILE_DIM 32 // Tile size, should be a multiple of WARP_SIZE (32)

__global__ void square_matrix_multiply_kernel(const float* A, const float* B, float* C, int N) {
    // Block row and column
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread row and column within the tile
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Base address for C
    int C_base_idx = N * TILE_DIM * blockRow + TILE_DIM * blockCol;

    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    float Cvalue = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_DIM - 1) / TILE_DIM; ++tile) {
        // Load A and B tiles into shared memory
        int A_idx = N * (TILE_DIM * tile + threadRow) + TILE_DIM * blockCol + threadCol;
        int B_idx = N * (TILE_DIM * blockRow + threadRow) + TILE_DIM * tile + threadCol;

        if ((TILE_DIM * tile + threadRow < N) && (TILE_DIM * blockCol + threadCol < N)) {
            sA[threadRow][threadCol] = A[A_idx];
        } else {
            sA[threadRow][threadCol] = 0.0f;
        }

        if ((TILE_DIM * blockRow + threadRow < N) && (TILE_DIM * tile + threadCol < N)) {
            sB[threadRow][threadCol] = B[B_idx];
        } else {
            sB[threadRow][threadCol] = 0.0f;
        }

        __syncthreads();

        // Perform computation on the tile
        for (int k = 0; k < TILE_DIM; ++k) {
            Cvalue += sA[threadRow][k] * sB[k][threadCol];
        }
        __syncthreads();
    }

    // Write result to global memory
    int C_idx = N * (TILE_DIM * blockRow + threadRow) + (TILE_DIM * blockCol + threadCol);
    if ((TILE_DIM * blockRow + threadRow < N) && (TILE_DIM * blockCol + threadCol < N)) {
        C[C_idx] = Cvalue;
    }
}

torch::Tensor square_matrix_multiply_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0); // Assuming square matrices

    auto C = torch::zeros({N, N}, A.options());

    // Calculate grid and block dimensions
    int block_size = TILE_DIM;
    dim3 dimBlock(block_size, block_size);
    dim3 dimGrid((N + block_size - 1) / block_size, (N + block_size - 1) / block_size);

    square_matrix_multiply_kernel<<<dimGrid, dimBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\n", cudaGetErrorString(err));
    }

    return C;
}
